/**
 * Golden `getImgProps` results from next@16.4.2. Do not edit by hand.
 *
 * Generated once, outside the repository, by running Next.js's own CommonJS
 * `dist/shared/lib/get-img-props.js` and `image-loader.js` from the
 * next@16.4.2 npm tarball under Node.js, with `imageConfigDefault` merged with
 * `path: '/_void/image'` and each case's `config`, normalized as Next.js's
 * `config.js` does (with Void's `/assets/**` static-import local pattern) and
 * prepared with `prepareImageConfig` (production client cases keep only the
 * keys Next.js inlines into client bundles). `imagePropsGolden` ran with
 * `NODE_ENV=production`; `imagePropsDevGolden` ran with
 * `NODE_ENV=development` and records thrown errors and `console.warn`
 * messages verbatim (the test adapts Next.js product names and links).
 * `getImageProps` cases deleted `undefined` keys as Next.js's
 * `getImageProps()` does. Prop values equal to `'[function]'` were replaced
 * with no-op functions, and `loader` / `defaultLoader` name the loaders in
 * `image-props.test.ts`.
 */
import type { ImageConfig } from '../../src/image/config.ts';
import type { ImageRenderState } from '../../src/image/types.ts';

export type ImagePropsGoldenCase = {
  name: string;
  props: Record<string, unknown>;
  /** User `images` config, before normalization. */
  config?: ImageConfig;
  /** `client`: the production client config, without patterns. Default `server`. */
  consumer?: 'client' | 'server';
  state?: ImageRenderState;
  /** Named `loader` prop. */
  loader?: string;
  /** Named `images.loaderFile` export; `missing` = no default export. */
  defaultLoader?: string;
  /** `getImageProps`: `undefined` keys deleted, no `meta`. */
  api?: 'getImageProps';
  expected: { props?: Record<string, unknown>; meta?: Record<string, unknown>; error?: string };
};

export type ImagePropsDevGoldenCase = ImagePropsGoldenCase & {
  /** `console.warn` messages, in order. */
  warnings: Array<string>;
};

